<div class="heading"><div><span class="eyebrow">CHECKOUT</span><h1>Record a sale</h1></div><a class="button" href="<?= site_url('sales/history') ?>">Sales history</a></div><section class="panel form-grid"><form method="post" action="<?= site_url('sales') ?>"><?= csrf_field() ?><label>Product<select name="product_id" required><option value="">Choose a product</option><?php foreach($products as $p): ?><option value="<?= $p['id'] ?>" <?= old('product_id')==$p['id']?'selected':'' ?>><?= esc($p['name']) ?> - $<?= number_format((float)$p['price'],2) ?> - <?= (int)$p['stock_quantity'] ?> in stock</option><?php endforeach ?></select></label><label>Customer <span class="muted">Optional</span><select name="customer_id"><option value="">Walk-in customer</option><?php foreach($customers as $c): ?><option value="<?= $c['id'] ?>" <?= old('customer_id')==$c['id']?'selected':'' ?>><?= esc($c['full_name']) ?></option><?php endforeach ?></select></label><label>Quantity<input type="number" name="quantity" min="1" step="1" value="<?= esc(old('quantity')?:'1') ?>" required></label><button class="button primary">Complete sale</button></form></section>